        const s = await connectShellSessionReady(args.port, { totalMs: 8000 }).catch(() => null)
        s?.close()
      } catch {}
      try { child.kill() } catch {}
      await sleep(1500)
    }
  }
}

main().catch((e) => { console.error(e); process.exit(1) })

