    child.stderr?.on('data', (c: Buffer) => { out += c.toString('utf8') })
    child.on('error', () => finish(false, '설치되어 있지 않음'))
    child.on('close', (code) => {
      const v = out.trim().split(/\r?\n/)[0]?.slice(0, 60) ?? ''
      finish(code === 0, code === 0 ? (v || '설치됨') : `종료 코드 ${code}`)
    })
  })
}

