              ))}
            </div>
          )}
          <div className="ai-compose">
            <button className="ai-adv-toggle" onClick={() => setShowAdvanced((v) => !v)}
              title="자동 반복·데이터 반복 등 고급 실행 옵션">
              <span className="ai-adv-caret">{showAdvanced ? '▾' : '▸'}</span>
