const readyIds = (detTruth?.candidates ?? []).filter((c) => c.ready).map((c) => c.id).sort()
const shownIds = [...(aiStep.cards ?? [])].sort()
check('W5', '온보딩이 보여주는 방법이 실제 탐지 결과와 같다',
