check('I2d', '설치본에서 뒤로/앞으로가 동작한다', nav.ok === true,
  nav.ok
    ? `이동 → 뒤로(${String(nav.back).slice(0, 34)}) → 앞으로(${String(nav.fwd).slice(0, 30)})`
    : `${nav.why ?? ''} 뒤로=${String(nav.back).slice(0, 34)} 앞으로=${String(nav.fwd).slice(0, 34)}`)

